<?php
namespace App\Models;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;
/** Provides one on one behavior within the WorkIntel application. */ class OneOnOne extends Model{protected $fillable=['uuid','workspace_id','member_id','manager_member_id','scheduled_at','occurred_at','status','agenda','private_manager_notes','shared_notes','action_items','next_meeting_at','created_by'];/** Defines attribute casting rules for the model. */ protected function casts():array{return ['scheduled_at'=>'datetime','occurred_at'=>'datetime','shared_notes'=>'array','action_items'=>'array','next_meeting_at'=>'datetime'];}/** Handles the member operation for the current WorkIntel workflow. */ public function member():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'member_id');}/** Handles the manager operation for the current WorkIntel workflow. */ public function manager():BelongsTo{return $this->belongsTo(WorkspaceMember::class,'manager_member_id');}}
